$old_fk_rename$                    -- We have a rename. Find all affected FKs, rename their triggers and update their metadata.
                    DECLARE
                        fk_rec RECORD;
                        uk_rec RECORD;
                        new_column_names name[];
                        new_foreign_key_name name;
                        new_uk_update_trigger name;
                        new_uk_delete_trigger name;
