    IF pg_catalog.strpos(changed, $old_rk0$    v_missing_excluded name;
$old_rk0$) = 0 OR pg_catalog.strpos(changed, $mark_rk0$    v_unique_key_columns_before jsonb;
$mark_rk0$) > 0 THEN
